    if clean_answer in ["not enough information", "unknown", "none", "nan", "inf", "null", "error", "unauthorized"]:
        return clean_answer  # Return the string as is for these specific cases, or "0" if strictly numeric expected. 
        # Based on failed examples returning '0' or 'Not enough information', we return the string.
        # But if the prompt asked for a number and got text, returning the text might fail grading if it expects a number.
