import re
from typing import Optional, List, Dict, Any


def handle_0de6cc(question: str, tools: Any) -> Optional[str]:
    """
    Pre-processes questions that require structured tool usage (lookup, financials, calculator)
    to improve accuracy over raw LLM calls. Returns the final answer string if handled,
    or None to let the original harness take over.
    """

    # 1. Handle Portfolio Questions (already partially handled by original harness, but we can refine or extend)
    # The original harness checks for "A-XXXX" pattern. Let's keep that logic but ensure it works.
    m = re.search(r"\bA-\d+\b", question)
    if m:
        account = m.group(0)
        if not tools.is_authorized(account):
            return "UNAUTHORIZED"
        # Original harness returns total_value as string
        try:
            data = tools.get_portfolio(account)
            return str(data["total_value"])
        except Exception:
            return None

    # 2. Handle Growth Questions: "By what percentage did X change from FY2023 to FY2024?"
    # Pattern: "By what percentage did [Ticker/Name]'s [metric] change from FY2023 to FY2024?"
    # We extract the company name and metric.
    growth_match = re.search(
        r"By what percentage did\s+([^\s'']+'s?)\s+([a-zA-Z_]+)\s+change\s+from\s+F[YZ]2023\s+to\s+F[YZ]2024",
        question,
        re.IGNORECASE
    )
    if growth_match:
        company_name = growth_match.group(1).strip("'s").strip()
        metric = growth_match.group(2).lower()

        # Normalize company name
        clean_name = company_name.replace("Co.", "").replace("Co '", "").strip()

        try:
            ticker = tools.lookup_ticker(clean_name)
            if not ticker:
                return None

            # Get values
            val2023 = tools.get_financials(ticker, metric, "FY2023")
            val2024 = tools.get_financials(ticker, metric, "FY2024")

            v23 = float(val2023["value"])
            v24 = float(val2024["value"])

            if v23 == 0:
                return "0"

            # Calculate percentage change
            pct_change = tools.calculator(f"({v24} - {v23}) / {v23} * 100")

            # Round to 1 decimal place
            rounded = round(pct_change, 1)
            return str(rounded)
        except Exception:
            return None

    # 3. Handle Multi-hop / Ownership Questions: "X is owned by Y. What [metric] did Y report...?"
    # Pattern: "[Company] is owned by another listed company. What [metric] did that parent report for FY2024?"
    owner_match = re.search(
        r"(\w+(?:\s+\w+)*)\s+is\s+owned\s+by\s+another\s+listed\s+company\.\s+What\s+([a-zA-Z_]+)\s+did\s+that\s+parent\s+report\s+for\s+F[YZ]2024",
        question,
