def _vote(tools_llm):
    def call(prompt, max_tokens=256, system=None):
        outs = [tools_llm(prompt + ("\n" * i), max_tokens=max_tokens, system=system) for i in range(4)]
        return max(set(outs), key=outs.count)
    return call


