    growth_ar_pattern = 'بماذا تغيرت إيرادات/صافي ربح\\s+([^\\s]+?)\\s+من\\s+(FY\\d{4})\\s+إلى\\s+(FY\\d{4})\\?'
    growth_match_en = re.search(growth_en_pattern, question)
    growth_match_ar = re.search(growth_ar_pattern, question)
    if growth_match_en or growth_match_ar:
        company_name = growth_match_en.group(1) if growth_match_en else growth_match_ar.group(1)
        company_name = re.sub("'\\s+revenue|'\\s+net_income|'\\s+change", '', company_name).strip()
        company_name = re.sub('\\s+(revenue|net_income)', '', company_name).strip()
        company_name = re.sub('\\s+change', '', company_name).strip()
        metric = growth_match_en.group(2) if growth_match_en else 'revenue'
        if growth_match_ar:
            if 'إيرادات' in question:
                metric = 'revenue'
            elif 'صافي ربح' in question:
                metric = 'net_income'
        period1 = growth_match_en.group(3) if growth_match_en else growth_match_ar.group(2)
        period2 = growth_match_en.group(4) if growth_match_en else growth_match_ar.group(3)
        try:
